// Custom shutdown hook
@Component
public class GracefulShutdownHook {

    private static final Logger logger = LoggerFactory.getLogger(GracefulShutdownHook.class);

    @EventListener
    public void handleContextClosing(ContextClosedEvent event) {
        logger.info("Received shutdown signal, starting graceful shutdown...");
        // Cleanup resources
        cleanupResources();
    }

    @PreDestroy
    public void cleanup() {
        logger.info("Performing cleanup before shutdown...");
        // Close database connections, file handles, etc.
    }

    private void cleanupResources() {
        // Custom cleanup logic
        try {
            // Wait for background tasks to complete
            Thread.sleep(5000);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

// Custom ApplicationListener for more control
@Component
public class ShutdownListener implements ApplicationListener<ContextClosedEvent> {

    @Override
    public void onApplicationEvent(ContextClosedEvent event) {
        // Graceful shutdown logic
        stopAcceptingNewRequests();
        waitForExistingRequestsToComplete();
        shutdownThreadPools();
    }
}

// Tomcat-specific graceful shutdown configuration
@Configuration
public class TomcatConfig {

    @Bean
    public GracefulShutdown gracefulShutdown() {
        return new GracefulShutdown();
    }

    @Bean
    public ConfigurableServletWebServerFactory webServerFactory(
            final GracefulShutdown gracefulShutdown) {
        TomcatServletWebServerFactory factory = new TomcatServletWebServerFactory();
        factory.addConnectorCustomizers(gracefulShutdown);
        return factory;
    }

    private static class GracefulShutdown implements TomcatConnectorCustomizer, 
            TomcatContextCustomizer, ApplicationListener<ContextClosedEvent> {

        private volatile Connector connector;

        @Override
        public void customize(Connector connector) {
            this.connector = connector;
        }

        @Override
        public void customize(Context context) {
            // Context customization if needed
        }

        @Override
        public void onApplicationEvent(ContextClosedEvent event) {
            if (this.connector != null) {
                this.connector.pause();
                Executor executor = this.connector.getProtocolHandler().getExecutor();
                if (executor instanceof ThreadPoolExecutor) {
                    try {
                        ThreadPoolExecutor threadPoolExecutor = (ThreadPoolExecutor) executor;
                        threadPoolExecutor.shutdown();
                        if (!threadPoolExecutor.awaitTermination(30, TimeUnit.SECONDS)) {
                            threadPoolExecutor.shutdownNow();
                        }
                    } catch (InterruptedException ex) {
                        Thread.currentThread().interrupt();
                    }
                }
            }
        }
    }
}
```

Key Points for Graceful Shutdown:
- Server Configuration: Enable graceful shutdown mode and set timeout
- Resource Cleanup: Use `@PreDestroy` methods to clean up resources
- Event Handling: Listen for `ContextClosedEvent` to perform custom shutdown logic
- Thread Pool Management: Properly shutdown custom thread pools and executors
- Request Completion: Allow in-flight HTTP requests to complete before shutdown
- Database Connections: Close database connections and connection pools
- External Resources: Clean up external service connections, file handles, etc.
- Monitoring: Log shutdown progress for debugging and monitoring

